description:
The small calculations every allocator does:

```cpp
bool isPowerOfTwo(std::uint64_t n);
std::uint64_t alignUp(std::uint64_t value, std::uint64_t align);
bool isAligned(const void* p, std::uint64_t align);
std::uint64_t sizeClass(std::uint64_t bytes);
std::uint64_t footprint(std::uint64_t bytes, std::uint64_t header, std::uint64_t align);
```

- **isPowerOfTwo**: 1, 2, 4, 8, ... are; 0 is not.
- **alignUp** rounds `value` up to a multiple of `align` (a power of two) using the bit trick from lesson 6.01, no division.
- **isAligned** says whether a pointer's address is a multiple of `align`.
- **sizeClass** rounds a request up to the size classes 16, 32, 64, 128, ... 4096. Requests of 0 bytes use class 16. Anything over 4096 returns 0, meaning "too big for the classes".
- **footprint** is the space a block really takes: header plus bytes, rounded up to `align`.

starter.solution.cpp:
#include <cstdint>

bool isPowerOfTwo(std::uint64_t n) { return false; }
std::uint64_t alignUp(std::uint64_t value, std::uint64_t align) { return value; }
bool isAligned(const void* p, std::uint64_t align) { return false; }
std::uint64_t sizeClass(std::uint64_t bytes) { return bytes; }
std::uint64_t footprint(std::uint64_t bytes, std::uint64_t header, std::uint64_t align) { return bytes; }

solution.solution.cpp:
#include <cstdint>

bool isPowerOfTwo(std::uint64_t n) { return n != 0 && (n & (n - 1)) == 0; }

std::uint64_t alignUp(std::uint64_t value, std::uint64_t align) { return (value + align - 1) & ~(align - 1); }

bool isAligned(const void* p, std::uint64_t align)
{
    return (reinterpret_cast<std::uintptr_t>(p) & (align - 1)) == 0;
}

std::uint64_t sizeClass(std::uint64_t bytes)
{
    if (bytes > 4096) return 0;
    std::uint64_t size{ 16 };
    while (size < bytes) size *= 2;
    return size;
}

std::uint64_t footprint(std::uint64_t bytes, std::uint64_t header, std::uint64_t align)
{
    return alignUp(header + bytes, align);
}

unitTests:
TEST("powers of two") {
    for (std::uint64_t n : { 1ull, 2ull, 4ull, 64ull, 4096ull, 1ull << 40 }) CHECK(isPowerOfTwo(n));
    for (std::uint64_t n : { 0ull, 3ull, 6ull, 12ull, 4095ull }) CHECK(!isPowerOfTwo(n));
}
TEST("aligning up") {
    CHECK_EQ(alignUp(0, 16), 0ull);
    CHECK_EQ(alignUp(1, 16), 16ull);
    CHECK_EQ(alignUp(16, 16), 16ull);
    CHECK_EQ(alignUp(17, 16), 32ull);
    CHECK_EQ(alignUp(4097, 4096), 8192ull);
    CHECK_EQ(alignUp(5, 1), 5ull);
}
TEST("aligned pointers") {
    alignas(64) static unsigned char block[128];
    CHECK(isAligned(block, 64));
    CHECK(isAligned(block + 16, 16));
    CHECK(!isAligned(block + 8, 16));
    CHECK(isAligned(block + 3, 1));
}
TEST("size classes") {
    CHECK_EQ(sizeClass(0), 16ull);
    CHECK_EQ(sizeClass(1), 16ull);
    CHECK_EQ(sizeClass(16), 16ull);
    CHECK_EQ(sizeClass(17), 32ull);
    CHECK_EQ(sizeClass(100), 128ull);
    CHECK_EQ(sizeClass(4096), 4096ull);
    CHECK_EQ(sizeClass(4097), 0ull);
}
TEST("footprint") {
    CHECK_EQ(footprint(24, 16, 16), 48ull);
    CHECK_EQ(footprint(1, 8, 16), 16ull);
    CHECK_EQ(footprint(0, 16, 16), 16ull);
}

